# Construct the incidence graph of PG(2,3) - the (4,6)-cage
# Points: 0..12, Lines: 13..25
# Each line is defined by equation a*x + b*y + c*z = 0

GF3 = [0, 1, 2]
points = []
for x in GF3:
    for y in GF3:
        for z in GF3:
            if (x, y, z) == (0, 0, 0):
                continue
            if x != 0:
                inv = pow(x, -1, 3)
                points.append((1, (y*inv)%3, (z*inv)%3))
            elif y != 0:
                inv = pow(y, -1, 3)
                points.append((0, 1, (z*inv)%3))
            else:
                points.append((0, 0, 1))

points = list(set(points))
print(f"Points: {len(points)}")

