# BFS from each vertex, find shortest cycle
def shortest_cycle_from(s):
    dist = [-1]*n
    parent = [-1]*n
    q = deque([s])
    dist[s] = 0
    min_cycle = 100
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v == parent[u]:
                continue
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                parent[v] = u
                q.append(v)
            elif dist[v] >= dist[u]:
                # Found a cycle
                cycle_len = dist[u] + dist[v] + 1
                if cycle_len < min_cycle:
                    min_cycle = cycle_len
    return min_cycle

girth = 100
